34	GameData.prototype.count=function(x,y,number){
35	    var directions=[{x:0,y:-1},{x:1,y:0},{x:0,y:1},{x:-1,y:0}]
36	    var count=0
37	    var _cmp=function(a,b){return a===b}
38	    if(typeof(number)!==typeof(1))_cmp=function(a,b){return b.indexOf(a)!==-1};
39	    for(var ii=0,d;d=directions[ii];ii++){
40	        var xx=x+d.x, yy=y+d.y
41	        if(_cmp(this.xy(xx,yy),number))count++;
42	    }
43	    return count
44	}
