71	GameData.prototype.fromGame=function(game){
72	    var _game=this
73	    _game.xsize=game.xsize
74	    _game.ysize=game.ysize
75	    _game.winScore=game.winScore
76	    _game.totalScore=game.xsize*game.ysize
77	    _game.playerId=game.playerId
78	    _game.winnerId=game.winnerId
79	    _game.player=[]
80	    for(var ii=0;ii<2;ii++){
81	        _game.player.push({
82	            score:game.player[ii].score,
83	            id:ii,
84	        })
85	    }
86	    _game.map=_game.cloneObj(game.map)
87	    _game.edgeCount={}
88	    _game.edgeCount[_game.EDGE_USED]=0
89	    _game.edgeCount[_game.EDGE_NOW]=0
90	    _game.edgeCount[_game.EDGE_WILL]=0
91	    _game.edgeCount[_game.EDGE_NOT]=0
92	    _game.scoreCount={}
93	    _game.scoreCount[_game.SCORE_0]=0
94	    _game.scoreCount[_game.SCORE_1]=0
95	    _game.scoreCount[_game.SCORE_2]=0
96	    _game.scoreCount[_game.SCORE_3]=0
97	    _game.scoreCount[_game.SCORE_4]=0
98	    for(var jj=1;jj<2*game.ysize+1;jj+=2){
99	        for(var ii=1;ii<2*game.xsize+1;ii+=2){
100	            var thiscount=_game.SCORE_0+_game.count(ii,jj,game.EDGE_USED)
101	            _game.xy(ii,jj,thiscount)
102	            _game.scoreCount[thiscount]++
103	        }
104	    }
105	    for(var jj=0;jj<2*game.ysize+1;jj++){
106	        for(var ii=0;ii<2*game.xsize+1;ii++){
107	            if((ii+jj)%2===0){
108	                if(ii%2===0)_game.xy(ii,jj,_game.POINT);
109	            } else {
110	                if(_game.xy(ii,jj)===game.EDGE_USED){
111	                    _game.xy(ii,jj,_game.EDGE_USED)
112	                    _game.edgeCount[_game.EDGE_USED]++
113	                } else if(_game.count(ii,jj,_game.SCORE_3)){
114	                    _game.xy(ii,jj,_game.EDGE_NOW)
115	                    _game.edgeCount[_game.EDGE_NOW]++
116	                } else if (_game.count(ii,jj,_game.SCORE_2)) {
117	                    _game.xy(ii,jj,_game.EDGE_WILL)
118	                    _game.edgeCount[_game.EDGE_WILL]++
119	                } else {
120	                    _game.xy(ii,jj,_game.EDGE_NOT)
121	                    _game.edgeCount[_game.EDGE_NOT]++
122	                }
123	            }
124	        }
125	    }
126	    _game.initConnectedRegion()
127	    return _game
128	}
129	GameData.prototype.cloneObj = function (data) {
130	    //深拷贝一个对象
131	    //return eval(JSON.stringify(data))
132	    if (data==null) return data;
133	    // array
134	    if (data instanceof Array) {
135	        var copy=[];
136	        // for (var i=0;i<data.length;i++) {
137	        for (var i in data) {
138	            copy[i] = this.cloneObj(data[i]);
139	        }
140	        return copy;
141	    }
142	    // object
143	    if (data instanceof Object) {
144	        var copy={};
145	        for (var i in data) {
146	            if (data.hasOwnProperty(i))
147	                copy[i]=this.cloneObj(data[i]);
148	        }
149	        return copy;
150	    }
151	    return data;
152	}
153	GameData.prototype.clone=function(){
154	    var game=this
155	    var _game=new GameData()
156	    for(var name in game){
157	        if(!game.hasOwnProperty(name))continue;
158	        _game[name]=game.cloneObj(game[name])
159	    }
160	    return _game
161	}
162	GameData.prototype.initConnectedRegion=function(){
163	    var game=this
164	    var visited = eval('['+Array(game.ysize+1).join('['+Array(game.xsize+1).join('false,')+'],')+']') // ysize*xsize的false
165	    var v=function(x,y,value){
166	        if(x<0||x>2*game.xsize)return true;
167	        if(y<0||y>2*game.ysize)return true;
168	        if(game.xy(x,y)!==game.SCORE_2 && game.xy(x,y)!==game.SCORE_3)visited[y>>1][x>>1]=true; // 不关心开放区域和已经被拿的分
169	        if(value==null)return visited[y>>1][x>>1];
170	        visited[y>>1][x>>1]=value
171	    }
172	    var directions=[{x:0,y:-1},{x:1,y:0},{x:0,y:1},{x:-1,y:0}]
173	    game.connectedRegion={}
174	    var stack10003 = [] // 能得分的区域
175	    game.scoreRegion=stack10003 
176	    var regionNum=0
177	    for(var y=1;y<2*game.ysize+1;y+=2){
178	        for(var x=1;x<2*game.xsize+1;x+=2){
179	            // --x,y-- 
180	            if(v(x,y))continue;
181	            regionNum++
182	            var queue=[{'x':x,'y':y}] // 把初始点加入队列
183	            var region={
184	                block:[],
185	                isRing:false,
186	                index:regionNum,
187	            } // 创建一个联通区域对象
188	            while(queue.length){
189	                var now = queue.shift()
190	                region.block.push(now) // 此处只是加到集合, 集合内部不反应格子的连接
191	                // TODO: 如果此处带判断的选择使用push还是unshift, 之后就无需再单独把集合变成反应连接的结构了
192	                v(now.x,now.y,true)
193	                if(game.xy(now.x,now.y)===game.SCORE_3){
194	                    // 当一个区域第一次发现能得分的格子时, 加入得分区域, 
195	                    // 第二次时标记为有环区域
196	                    if(stack10003.indexOf(region.index)===-1){
197	                        stack10003.push(region.index)
198	                    }
199	                    else region.isRing=true;
200	                }
201	                for(var ii=0,d;d=directions[ii];ii++){
202	                    // 判断四周的格式是否加到队列
203	                    var xx=now.x+d.x*2, yy=now.y+d.y*2
204	                    if(game.xy(now.x+d.x,now.y+d.y)!==game.EDGE_WILL && game.xy(now.x+d.x,now.y+d.y)!==game.EDGE_NOW)continue;
205	                    if(v(xx,yy))continue;
206	                    queue.push({'x':xx,'y':yy})
207	                }
208	            }
209	            game.connectedRegion[region.index]=region
210	            // --x,y-- 
211	        }
212	    }
213	    game.regionNum=regionNum
214	    game.maxIndex=regionNum
215	    game.area = eval('['+Array(game.ysize+1).join('['+Array(game.xsize+1).join('0,')+'],')+']') // ysize*xsize的0
216	    for(var index in game.connectedRegion){
217	        var region=game.connectedRegion[index]
218	        for(var ii=0,pt;pt=region.block[ii];ii++){
219	            game.areaxy(pt.x,pt.y,index)
220	        }
221	    }
222	    //重新排列各region, 并检测无法立刻得分的闭区域是否有环
223	    for(var index in game.connectedRegion){
224	        // 这里要注意index是字符串,不能用===
225	        var region=game.connectedRegion[index]
226	        if(region.block.length<=2)continue; // 长度小于2的自然是连接在一起的
227	        var now=region.block[0]
228	        var stack=[]
229	        for(var ii=0,d;d=directions[ii];ii++){
230	            var x=now.x+d.x*2, y=now.y+d.y*2
231	            if(game.areaxy(x,y)==index && game.xy(now.x+d.x,now.y+d.y)!==game.EDGE_USED)stack.push({'x':x,'y':y})
232	        }
233	        var visited = eval('['+Array(game.ysize+1).join('['+Array(game.xsize+1).join('false,')+'],')+']') // ysize*xsize的false
234	        var v=function(x,y,value){
235	            if(x<0||x>2*game.xsize)return true;
236	            if(y<0||y>2*game.ysize)return true;
237	            if(game.areaxy(x,y)!=index)visited[y>>1][x>>1]=true;
238	            if(value==null)return visited[y>>1][x>>1];
239	            visited[y>>1][x>>1]=value
240	        }
241	        v(now.x,now.y,true)
242	        var link=function(pt,fadd){
243	            var queue=[pt]
244	            while(queue.length){
245	                var pt = queue.shift()
246	                v(pt.x,pt.y,true)
247	                fadd(pt)
248	                for(var ii=0,d;d=directions[ii];ii++){
249	                    var xx=pt.x+d.x*2, yy=pt.y+d.y*2
250	                    if(game.xy(pt.x+d.x,pt.y+d.y)!==game.EDGE_WILL && game.xy(pt.x+d.x,pt.y+d.y)!==game.EDGE_NOW)continue;
251	                    if(v(xx,yy))continue;
252	                    queue.push({'x':xx,'y':yy})
253	                }
254	            }
255	        }
256	        var newblock=[now]
257	        link(stack[0],function(pt){newblock.push(pt)})
258	        if(stack.length>1){
259	            if(v(stack[1].x,stack[1].y)===true){
260	                region.isRing=true
261	            } else {
262	                link(stack[1],function(pt){newblock.unshift(pt)})
263	            }
264	        }
265	        region.block=newblock
266	    }
267	}
268	GameData.prototype.areaxy=function(x,y,value){
269	    var game=this
270	    if(x<0||x>2*game.xsize)return 'out range';
271	    if(y<0||y>2*game.ysize)return 'out range';
272	    if(value==null)return game.area[y>>1][x>>1];
273	    game.area[y>>1][x>>1]=~~value
274	}
