// temp perf probe
var vm = require('vm')
var fs = require('fs')
var path = require('path')
var sandbox = { console: console, Math: Object.create(Math) }
vm.createContext(sandbox)
var srcFiles = ['game.js', 'gamedata.js', 'player.js', 'rolloutAI.js']
for (var i = 0; i < srcFiles.length; i++) {
    vm.runInContext(fs.readFileSync(path.join(__dirname, srcFiles[i]), 'utf8'), sandbox)
}
var Game = sandbox.Game
var GameData = sandbox.GameData
var OffensiveKeeperAI = sandbox.OffensiveKeeperAI

function now() { var t = process.hrtime(); return t[0] * 1000 + t[1] / 1e6 }

// build a mid-game position by playing random OK moves for ~30 plies
function buildPos(plies) {
    var game = new Game().init(6, 6)
    var gd = new GameData().fromGame(game)
    var ai = new OffensiveKeeperAI()
    for (var i = 0; i < plies && gd.winnerId == null; i++) {
        ai.gameData = gd
        var w = ai.where()
        gd.putxy(w.x, w.y)
    }
    return gd
}

// measure clone
var gd = buildPos(30)
var N = 2000
var t0 = now()
for (var i = 0; i < N; i++) { gd.clone() }
console.log('clone: ' + ((now() - t0) / N).toFixed(3) + ' ms/op')

// measure putxy (on a fresh clone each time to avoid ending)
t0 = now()
var M = 2000
for (var i = 0; i < M; i++) {
    var c = gd.clone()
    // play one safe edge if exists
    var e = c.getAllEdges(c.EDGE_NOT)
    if (e.length) c.putxy(e[0].x, e[0].y)
}
console.log('clone+1putxy: ' + ((now() - t0) / M).toFixed(3) + ' ms/op')

// measure OK.where()
t0 = now()
var W = 5000
var ai = new OffensiveKeeperAI()
for (var i = 0; i < W; i++) { ai.gameData = gd; ai.where() }
console.log('OK.where: ' + ((now() - t0) / W).toFixed(3) + ' ms/op')

// measure a full rollout (OK vs OK to end) from this position
function rollout(gd0) {
    var sim = gd0.clone()
    var a = new OffensiveKeeperAI()
    var guard = 0
    while (sim.winnerId == null && guard++ < 200) {
        a.gameData = sim
        var w = a.where()
        if (!w || w.x == null) break
        sim.putxy(w.x, w.y)
    }
    return sim
}
t0 = now()
var R = 200
for (var i = 0; i < R; i++) { rollout(gd) }
console.log('full OK rollout from mid: ' + ((now() - t0) / R).toFixed(3) + ' ms/op')
console.log('edgeCounts NOW/NOT/WILL:', gd.edgeCount[gd.EDGE_NOW], gd.edgeCount[gd.EDGE_NOT], gd.edgeCount[gd.EDGE_WILL])

