// debug.js — replay a single ro vs gr game with full board dump
var vm = require('vm')
var fs = require('fs')
var path = require('path')
var sandbox = { console: console, Math: Object.create(Math) }
vm.createContext(sandbox)
var srcFiles = ['game.js', 'gamedata.js', 'player.js', 'rolloutAI.js']
for (var i = 0; i < srcFiles.length; i++) {
    vm.runInContext(fs.readFileSync(path.join(__dirname, srcFiles[i]), 'utf8'), sandbox)
}
var Game = sandbox.Game, GameData = sandbox.GameData
var OffensiveKeeperAI = sandbox.OffensiveKeeperAI, GreedyRandomAI = sandbox.GreedyRandomAI, RolloutAI = sandbox.RolloutAI

function createSeededRandom(seed){var s=seed>>>0;return function(){s=(s*1664525+1013904223)>>>0;return s/4294967296}}
sandbox.Math.random = createSeededRandom(parseInt(process.argv[4],10)>>>0)

function render(gd){
    // 6x6 boxes. Build a (2*ysize+1) x (2*xsize+1) char grid
    var Y=2*gd.ysize+1, X=2*gd.xsize+1
    var lines=[]
    for(var y=0;y<Y;y++){
        var line=''
        for(var x=0;x<X;x++){
            var v=gd.xy(x,y)
            if((x+y)%2===0){ line+='·' } // point
            else if(x%2===0){ // vertical edge position (x even, y odd)
                line += (v===gd.EDGE_USED)?'│':' '
            } else if(y%2===0){ // horizontal edge (x odd, y even)
                line += (v===gd.EDGE_USED)?'─':' '
            } else { // box (odd,odd)
                // box ownership: SCORE_PLAYER values 4 or 8 in game; in gamedata we kept map values?
                if(v===4)line+='A'; else if(v===8)line+='B'; else line+=' '
            }
            if(x%2===0 && x<X-1){
                // horizontal slot between points on even y
            }
        }
        lines.push(line)
    }
    return lines.join('\n')
}

var seed=parseInt(process.argv[4],10)>>>0
var game=new Game().init(6,6)
var gd=new GameData().fromGame(game)
var ro=new RolloutAI(), gr=new GreedyRandomAI()
var ai1=ro, ai2=gr  // ro first
var hist=[]
var ply=0
while(gd.winnerId==null && ply<200){
    var ai = gd.playerId===0?ai1:ai2
    ai.gameData=gd
    var w=ai.where()
    if(!w||w.x==null)break
    var before={now:gd.edgeCount[gd.EDGE_NOW],not:gd.edgeCount[gd.EDGE_NOT],will:gd.edgeCount[gd.EDGE_WILL],s0:gd.player[0].score,s1:gd.player[1].score}
    // print only near/after transition
    if(before.not<=8){
        console.log('--- ply '+ply+' player='+gd.playerId+'('+ (gd.playerId===0?'RO':'GR') +') move='+w.x+','+w.y+'  [NOW='+before.now+' NOT='+before.not+' WILL='+before.will+' score '+(gd.playerId===0?'RO':'GR')+'='+ (gd.playerId===0?before.s0:before.s1)+']')
        if(before.not<=4) console.log(render(gd))
    }
    gd.putxy(w.x,w.y)
    hist.push([w.x,w.y,gd.playerId])
    ply++
}
console.log('FINAL winner='+gd.winnerId+' scores='+gd.player[0].score+'/'+gd.player[1].score+' ply='+ply)

