var srcFiles = ['game.js', 'gamedata.js', 'player.js', 'rolloutAI.js']
for (var i = 0; i < srcFiles.length; i++) {
    vm.runInContext(fs.readFileSync(path.join(__dirname, srcFiles[i]), 'utf8'), sandbox)
}
var Game = sandbox.Game, GameData = sandbox.GameData
var RolloutAI = sandbox.RolloutAI, GreedyRandomAI = sandbox.GreedyRandomAI, OffensiveKeeperAI = sandbox.OffensiveKeeperAI

function createSeededRandom(seed){var s=seed>>>0;return function(){s=(s*1664525+1013904223)>>>0;return s/4294967296}}
sandbox.Math.random = createSeededRandom(parseInt(process.argv[4],10)>>>0)

function render(gd){
    var Y=2*gd.ysize+1, X=2*gd.xsize+1, lines=[]
    for(var y=0;y<Y;y++){
        var line=''
        for(var x=0;x<X;x++){
            var v=gd.xy(x,y)
            if((x+y)%2===0)line+='·'
            else if(x%2===0)line+=(v===gd.EDGE_USED)?'│':' '
            else if(y%2===0)line+=(v===gd.EDGE_USED)?'─':' '
            else { if(v===4)line+='A'; else if(v===8)line+='B'; else line+=' ' }
        }
        lines.push(line)
    }
    return lines.join('\n')
}

var seed=parseInt(process.argv[4],10)>>>0
var ai1Name=process.argv[2]||'ro', ai2Name=process.argv[3]||'gr'
var C={ro:RolloutAI,gr:GreedyRandomAI,ok:OffensiveKeeperAI}
var game=new Game().init(6,6)
var gd=new GameData().fromGame(game)
var ai1=new C[ai1Name](), ai2=new C[ai2Name]()
var ply=0, transitionSeen=false
while(gd.winnerId==null && ply<200){
    var ai = gd.playerId===0?ai1:ai2
    ai.gameData=gd
    var w=ai.where()
    if(!w||w.x==null)break
    var edgeType=gd.xy(w.x,w.y)
    var typeStr = edgeType===gd.EDGE_NOW?'TAKE':(edgeType===gd.EDGE_NOT?'safe':(edgeType===gd.EDGE_WILL?'SAC':'?'))
    if(gd.edgeCount[gd.EDGE_NOT]<=6){
