    }
    gd.putxy(w.x,w.y)
    ply++
}
console.log('FINAL winner='+gd.winnerId+' ('+(gd.winnerId===0?ai1Name:ai2Name)+') sc='+gd.player[0].score+'/'+gd.player[1].score)

