// solver.js — negamax endgame solver + experiments (temp)
var vm = require('vm')
var fs = require('fs')
var path = require('path')
var sandbox = { console: console, Math: Object.create(Math) }
vm.createContext(sandbox)
var srcFiles = ['game.js', 'gamedata.js', 'player.js', 'rolloutAI.js']
for (var i = 0; i < srcFiles.length; i++) {
    vm.runInContext(fs.readFileSync(path.join(__dirname, srcFiles[i]), 'utf8'), sandbox)
}
var Game = sandbox.Game, GameData = sandbox.GameData
var RolloutAI = sandbox.RolloutAI, GreedyRandomAI = sandbox.GreedyRandomAI, OffensiveKeeperAI = sandbox.OffensiveKeeperAI

function createSeededRandom(seed){var s=seed>>>0;return function(){s=(s*1664525+1013904223)>>>0;return s/4294967296}}

// fast clone from rolloutAI.js
var nodes=0
function negamax(gd, alpha, beta, depth){
    nodes++
    if(gd.winnerId!=null || depth<=0){
        return gd.player[gd.playerId].score - gd.player[1-gd.playerId].score
    }
    // generate moves
    var takes = gd.getAllEdges(gd.EDGE_NOW)
    var moves = takes.slice()
    // allow yields (WILL edges) only if no takes, OR always (for doublecross correctness)
    if(takes.length===0){
        var wills = gd.getAllEdges(gd.EDGE_WILL)
        // order: prefer edges of smallest region
        for(var i=0;i<wills.length;i++) moves.push(wills[i])
    }
    if(moves.length===0){
        return gd.player[gd.playerId].score - gd.player[1-gd.playerId].score
    }
    var best=-1e9
    for(var i=0;i<moves.length;i++){
        var c = gd.fastClone()
        c.putxy(moves[i].x, moves[i].y)
        var v = -negamax(c, -beta, -alpha, depth-1)
        if(v>best)best=v
        if(best>alpha)alpha=best
        if(alpha>=beta)break
    }
    return best
}

// build a position by playing ai vs ai until a given ply, then solve
function buildUntil(ai1Cls, ai2Cls, seed, untilPly){
    sandbox.Math.random = createSeededRandom(seed>>>0)
    var game=new Game().init(6,6)
    var gd=new GameData().fromGame(game)
    var ai1=new ai1Cls(), ai2=new ai2Cls()
    var ply=0
    while(gd.winnerId==null && ply<untilPly){
        var ai=gd.playerId===0?ai1:ai2; ai.gameData=gd; var w=ai.where()
        if(!w||w.x==null)break
        gd.putxy(w.x,w.y); ply++
    }
    return gd
}

// Solve the traced losing position: gr(p0) vs ro(p1), at transition ply42
var seed=3345186153
var gd=buildUntil(GreedyRandomAI, RolloutAI, seed, 42)
console.log('at ply42: player to move='+gd.playerId+' NOW='+gd.edgeCount[gd.EDGE_NOW]+' NOT='+gd.edgeCount[gd.EDGE_NOT]+' WILL='+gd.edgeCount[gd.EDGE_WILL]+' sc='+gd.player[0].score+'/'+gd.player[1].score)
nodes=0
var t0=Date.now()
var val=negamax(gd, -1e9, 1e9, 80)
console.log('negamax value (from p'+gd.playerId+' perspective)='+val+' nodes='+nodes+' time='+(Date.now()-t0)+'ms')
console.log('  => p'+gd.playerId+' ('+(gd.playerId===0?'GR':'RO')+') final diff perspective; positive means p'+gd.playerId+' ahead')
console.log('  total boxes=36, so if val>0 the player-to-move wins the remaining battle by '+val)

