////////////////// RolloutAI //////////////////
RolloutAI=function(){
    OffensiveKeeperAI.call(this)
    return this
}
RolloutAI.prototype = Object.create(OffensiveKeeperAI.prototype)
RolloutAI.prototype.constructor = RolloutAI

// ============ fast clone (extend GameData; gamedata.js is protected) ============
// The built-in GameData.clone uses a slow recursive cloneObj. This specialized
// copy knows the exact shape of GameData and avoids instanceof / for-in overhead.
GameData.prototype.fastClone = function(){
    var g = new GameData()
    g.xsize = this.xsize
    g.ysize = this.ysize
    g.winScore = this.winScore
    g.totalScore = this.totalScore
    g.playerId = this.playerId
    g.winnerId = this.winnerId
    g.endImmediately = this.endImmediately
    g.regionNum = this.regionNum
    g.maxIndex = this.maxIndex
    g.player = [
        {score:this.player[0].score, id:0},
        {score:this.player[1].score, id:1}
    ]
    // map: rows of ints
    var nrows = this.map.length
    g.map = new Array(nrows)
    for (var y=0;y<nrows;y++){
        var sr=this.map[y], cols=sr.length, dr=new Array(cols)
        for (var x=0;x<cols;x++) dr[x]=sr[x]
        g.map[y]=dr
    }
    // area
    if (this.area){
        var ar=this.area.length
        g.area=new Array(ar)
        for (var y=0;y<ar;y++){
            var sr=this.area[y], cols=sr.length, dr=new Array(cols)
            for (var x=0;x<cols;x++) dr[x]=sr[x]
            g.area[y]=dr
        }
    }
    // edgeCount / scoreCount (small plain objects)
    g.edgeCount={}
    for (var k in this.edgeCount) g.edgeCount[k]=this.edgeCount[k]
    g.scoreCount={}
    for (var k in this.scoreCount) g.scoreCount[k]=this.scoreCount[k]
    // scoreRegion (array of indices)
    if (this.scoreRegion) g.scoreRegion=this.scoreRegion.slice()
    // connectedRegion: index -> {block:[{x,y}], isRing, index} or null
    g.connectedRegion={}
    for (var idx in this.connectedRegion){
        var r=this.connectedRegion[idx]
        if(!r){ g.connectedRegion[idx]=null; continue }
        var blk=r.block, n=blk.length, nblk=new Array(n)
        for (var i=0;i<n;i++){ var p=blk[i]; nblk[i]={x:p.x,y:p.y} }
        g.connectedRegion[idx]={block:nblk, isRing:r.isRing, index:r.index}
    }
    return g
}

// ============ tunable rollout parameters ============
RolloutAI.prototype.RO_MAX_CANDIDATES = 18   // max safe-move candidates evaluated per decision
RolloutAI.prototype.RO_ROLLOUTS       = 24   // rollouts per candidate
RolloutAI.prototype.RO_THRESH         = 30   // only rollout when EDGE_NOT <= this; earlier -> cheap move
RolloutAI.prototype.RO_ENDGAME        = false // reserved

// ============ fast endgame / rollout policy ============
// Greedy take + sacrifice-smallest + random-safe-opening. Currently unused
// for the real endgame (OffensiveKeeperAI's control play is stronger) but
// kept as a building block.
RolloutAI.prototype.policyWhere = function(gd){
    if(gd.edgeCount[gd.EDGE_NOW]>0){
        if(gd.scoreRegion.length>0){
            return gd.getOneEdgeFromRegionIndex(gd.scoreRegion[0])
        }
        return gd.getAllEdges(gd.EDGE_NOW)[0]
    }
    if(gd.edgeCount[gd.EDGE_NOT]>0){
        return this.getRandWhere(gd.EDGE_NOT)
    }
    return gd.getOneEdgeFromRegion(gd.getMinConnectedRegion())
}

// cached rollout-policy AI (stateless except gameData, safe to reuse)
RolloutAI.prototype._rolloutAI = function(){
    if(!this.__rollAI) this.__rollAI = new OffensiveKeeperAI()
    return this.__rollAI
}

// pick diverse safe-edge candidates
RolloutAI.prototype._openingCandidates = function(gd){
    var all = gd.getAllEdges(gd.EDGE_NOT)
    if (all.length <= this.RO_MAX_CANDIDATES) return all
    // Fisher-Yates shuffle (seeded stream) then take cap
    for (var i=all.length-1;i>0;i--){
        var j=(Math.random()*(i+1))|0
        var t=all[i]; all[i]=all[j]; all[j]=t
    }
    return all.slice(0, this.RO_MAX_CANDIDATES)
}

// play out `sim` to terminal using the rollout policy (mutates sim)
RolloutAI.prototype._rolloutToEnd = function(sim, policy){
    policy = policy || 'ok'
    var guard=0
    while (sim.winnerId==null && guard++<400){
        var w
        if(policy==='greedy') w = this.policyWhere(sim)
        else { var pol=this._rolloutAI(); pol.gameData=sim; w=pol.where() }
        if (!w || w.x==null) break
        sim.putxy(w.x, w.y)
    }
}

// choose the best safe edge by averaging rollout score-difference
RolloutAI.prototype.openingMove = function(gd){
    var me = gd.playerId
    var cands = this._openingCandidates(gd)
    var R = this.RO_ROLLOUTS
    var best = cands[0], bestScore = -1e9
    for (var ci=0; ci<cands.length; ci++){
        var c = cands[ci]
        var sum = 0
        for (var r=0; r<R; r++){
            var sim = gd.fastClone()
            sim.putxy(c.x, c.y)            // EDGE_NOT: no score, turn flips
            this._rolloutToEnd(sim)
            sum += sim.player[me].score - sim.player[1-me].score
        }
        var avg = sum / R
        if (avg > bestScore + 1e-9){ bestScore = avg; best = c }
    }
    return best
}

RolloutAI.prototype.where = function(){
    var gd = this.gameData
    // pure opening: no immediate score available, safe moves remain
    if (gd.edgeCount[gd.EDGE_NOW]===0 && gd.edgeCount[gd.EDGE_NOT]>0){
        if (gd.edgeCount[gd.EDGE_NOT] <= this.RO_THRESH){
            return this.openingMove(gd)
        }
        // very early: cheap safe move (still no give-away)
        return this.getRandWhere(gd.EDGE_NOT)
    }
    // scoring / transition / sacrifice: OffensiveKeeperAI's control endgame
    return OffensiveKeeperAI.prototype.where.call(this)
}

