// average rollout score-difference for a candidate under one policy
RolloutAI.prototype._evalCandidate = function(gd, c, me, R, policy){
    var sum = 0
    for (var r=0; r<R; r++){
        var sim = gd.fastClone()
        sim.putxy(c.x, c.y)            // EDGE_NOT: no score, turn flips
        this._rolloutToEnd(sim, policy)
        sum += sim.player[me].score - sim.player[1-me].score
    }
    return sum / R
}

// choose the best safe edge by averaging rollout score-difference
RolloutAI.prototype.openingMove = function(gd){
    var me = gd.playerId
    var cands = this._openingCandidates(gd)
    var R = this.RO_ROLLOUTS
    var pol = this.RO_POLICY
    var best = cands[0], bestScore = -1e9
    for (var ci=0; ci<cands.length; ci++){
        var c = cands[ci]
        var score
        if(pol==='robust'){
            // worst-case across opponent models: be strong vs both OK and greedy
            score = Math.min(this._evalCandidate(gd,c,me,R,'ok'), this._evalCandidate(gd,c,me,R,'greedy'))
        } else {
            score = this._evalCandidate(gd,c,me,R,pol)
        }
        if (score > bestScore + 1e-9){ bestScore = score; best = c }
    }
    return best
}

