RolloutAI.prototype.detWhere = function(gd){
    if(gd.edgeCount[gd.EDGE_NOW]>0 || gd.edgeCount[gd.EDGE_NOT]===0){
        var pol=this._rolloutAI(); pol.gameData=gd; return pol.where()
    }
    return this.detOpeningWhere(gd)
}

