// ---- Common Random Numbers rollout ----
// The rollout's only source of variance is the random opening (OK's endgame
// is deterministic once EDGE_NOT hits 0). By driving ALL random choices from
// a local RNG seeded identically across candidates (for the same rollout
// index r), candidate outcomes become positively correlated, slashing the
// variance of the ranking. This preserves the random policy's unbiasedness
// (unlike a fixed heuristic) while needing far fewer rollouts.
RolloutAI.prototype._makeRng = function(seed){
    var s = (seed>>>0)||1
    return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296 }
}
RolloutAI.prototype._randEdge = function(sim, type, rng){
    var count = sim.edgeCount[type]
    if(!count) return null
    var idx = (rng()*count)|0
    if(idx>=count)idx=count-1
    var Y=2*sim.ysize+1, X=2*sim.xsize+1
    for(var y=0;y<Y;y++){ var row=sim.map[y]
        for(var x=0;x<X;x++){ if(row[x]===type){ if(!idx)return {x:x,y:y}; idx-- } }
