////////////////// RolloutAI //////////////////
RolloutAI=function(){
    OffensiveKeeperAI.call(this)
    return this
}
RolloutAI.prototype = Object.create(OffensiveKeeperAI.prototype)
RolloutAI.prototype.constructor = RolloutAI

// ============ fast clone (extend GameData; gamedata.js is protected) ============
// The built-in GameData.clone uses a slow recursive cloneObj. This specialized
// copy knows the exact shape of GameData and avoids instanceof / for-in overhead.
GameData.prototype.fastClone = function(){
    var g = new GameData()
    g.xsize = this.xsize
    g.ysize = this.ysize
    g.winScore = this.winScore
    g.totalScore = this.totalScore
    g.playerId = this.playerId
    g.winnerId = this.winnerId
    g.endImmediately = this.endImmediately
    g.regionNum = this.regionNum
    g.maxIndex = this.maxIndex
    g.player = [
        {score:this.player[0].score, id:0},
        {score:this.player[1].score, id:1}
    ]
    // map: rows of ints
    var nrows = this.map.length
    g.map = new Array(nrows)
    for (var y=0;y<nrows;y++){
        var sr=this.map[y], cols=sr.length, dr=new Array(cols)
        for (var x=0;x<cols;x++) dr[x]=sr[x]
        g.map[y]=dr
    }
    // area
    if (this.area){
        var ar=this.area.length
        g.area=new Array(ar)
        for (var y=0;y<ar;y++){
            var sr=this.area[y], cols=sr.length, dr=new Array(cols)
            for (var x=0;x<cols;x++) dr[x]=sr[x]
            g.area[y]=dr
        }
    }
    // edgeCount / scoreCount (small plain objects)
    g.edgeCount={}
    for (var k in this.edgeCount) g.edgeCount[k]=this.edgeCount[k]
    g.scoreCount={}
    for (var k in this.scoreCount) g.scoreCount[k]=this.scoreCount[k]
    // scoreRegion (array of indices)
    if (this.scoreRegion) g.scoreRegion=this.scoreRegion.slice()
    // connectedRegion: index -> {block:[{x,y}], isRing, index} or null
    g.connectedRegion={}
    for (var idx in this.connectedRegion){
        var r=this.connectedRegion[idx]
        if(!r){ g.connectedRegion[idx]=null; continue }
        var blk=r.block, n=blk.length, nblk=new Array(n)
        for (var i=0;i<n;i++){ var p=blk[i]; nblk[i]={x:p.x,y:p.y} }
        g.connectedRegion[idx]={block:nblk, isRing:r.isRing, index:r.index}
    }
    return g
}

// ============ tunable rollout parameters ============
RolloutAI.prototype.RO_MAX_CANDIDATES = 22   // max safe-move candidates evaluated per decision
RolloutAI.prototype.RO_ROLLOUTS = 32   // rollouts per candidate per policy
RolloutAI.prototype.RO_THRESH = 32   // only rollout when EDGE_NOT <= this; earlier -> cheap move
RolloutAI.prototype.RO_POLICY = 'crn' // 'ok' | 'greedy' | 'robust'(min of ok&greedy)

// ============ fast endgame / rollout policy ============
// Greedy take + sacrifice-smallest + random-safe-opening. Currently unused
// for the real endgame (OffensiveKeeperAI's control play is stronger) but
// kept as a building block.
RolloutAI.prototype.policyWhere = function(gd){
    if(gd.edgeCount[gd.EDGE_NOW]>0){
        if(gd.scoreRegion.length>0){
            return gd.getOneEdgeFromRegionIndex(gd.scoreRegion[0])
        }
        return gd.getAllEdges(gd.EDGE_NOW)[0]
    }
    if(gd.edgeCount[gd.EDGE_NOT]>0){
        return this.getRandWhere(gd.EDGE_NOT)
    }
    return gd.getOneEdgeFromRegion(gd.getMinConnectedRegion())
}

// cached rollout-policy AI (stateless except gameData, safe to reuse)
RolloutAI.prototype._rolloutAI = function(){
    if(!this.__rollAI) this.__rollAI = new OffensiveKeeperAI()
    return this.__rollAI
}

// Deterministic opening policy for low-variance rollouts.
// OK's *endgame* is already deterministic; only its opening uses randomness.
// Making the rollout's opening deterministic too turns the whole playout
// deterministic, so a small R yields a clean ranking of candidate moves.
// Heuristic: among safe edges, pick the one creating the fewest new 2-edge
// boxes (a "patient" opening that keeps the board uncommitted), scan-order tiebreak.
RolloutAI.prototype._detDirs = [{x:0,y:-1},{x:1,y:0},{x:0,y:1},{x:-1,y:0}]
RolloutAI.prototype.detOpeningWhere = function(gd){
    var best=null, bestCost=1e9
    var Y=2*gd.ysize+1, X=2*gd.xsize+1
    for(var y=0;y<Y;y++){
        var row=gd.map[y]
        for(var x=0;x<X;x++){
            if(row[x]!==gd.EDGE_NOT)continue
            var cost=0, d=this._detDirs
            for(var i=0;i<4;i++){
                var bx=x+d[i].x, by=y+d[i].y
                if(by<0||by>=Y||bx<0||bx>=X)continue
                if(gd.map[by][bx]===gd.SCORE_1)cost++
            }
            if(cost<bestCost){bestCost=cost;best={x:x,y:y}}
        }
    }
    return best
}

// deterministic policy: patient opening + OK endgame
RolloutAI.prototype.detWhere = function(gd){
    if(gd.edgeCount[gd.EDGE_NOW]>0 || gd.edgeCount[gd.EDGE_NOT]===0){
        var pol=this._rolloutAI(); pol.gameData=gd; return pol.where()
    }
    return this.detOpeningWhere(gd)
}

// ---- Common Random Numbers rollout ----
// The rollout's only source of variance is the random opening (OK's endgame
// is deterministic once EDGE_NOT hits 0). By driving ALL random choices from
// a local RNG seeded identically across candidates (for the same rollout
// index r), candidate outcomes become positively correlated, slashing the
// variance of the ranking. This preserves the random policy's unbiasedness
// (unlike a fixed heuristic) while needing far fewer rollouts.
RolloutAI.prototype._makeRng = function(seed){
    var s = (seed>>>0)||1
    return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296 }
}
RolloutAI.prototype._randEdge = function(sim, type, rng){
    var count = sim.edgeCount[type]
    if(!count) return null
    var idx = (rng()*count)|0
    if(idx>=count)idx=count-1
    var Y=2*sim.ysize+1, X=2*sim.xsize+1
    for(var y=0;y<Y;y++){ var row=sim.map[y]
        for(var x=0;x<X;x++){ if(row[x]===type){ if(!idx)return {x:x,y:y}; idx-- } }
    }
    return null
}
// CRN rollout policy: random opening/transition-take use `rng`; endgame uses
// OffensiveKeeperAI (deterministic when EDGE_NOT==0).
RolloutAI.prototype.crnWhere = function(sim, rng){
    var now=sim.edgeCount[sim.EDGE_NOW], not=sim.edgeCount[sim.EDGE_NOT]
    if(now>0 && not>0){
        // transition: a free box appeared while safe moves remain -> take it
        return this._randEdge(sim, sim.EDGE_NOW, rng)
    }
    if(not>0){
        return this._randEdge(sim, sim.EDGE_NOT, rng)
    }
    // pure endgame or forced sacrifice: OffensiveKeeperAI (deterministic here)
    var pol=this._rolloutAI(); pol.gameData=sim; return pol.where()
}
RolloutAI.prototype._openingCandidates = function(gd){
    var all = gd.getAllEdges(gd.EDGE_NOT)
    if (all.length <= this.RO_MAX_CANDIDATES) return all
    // Fisher-Yates shuffle (seeded stream) then take cap
    for (var i=all.length-1;i>0;i--){
        var j=(Math.random()*(i+1))|0
        var t=all[i]; all[i]=all[j]; all[j]=t
    }
    return all.slice(0, this.RO_MAX_CANDIDATES)
}

// play out `sim` to terminal using the rollout policy (mutates sim)
RolloutAI.prototype._rolloutToEnd = function(sim, policy, rng){
    policy = policy || 'ok'
    var guard=0
    while (sim.winnerId==null && guard++<400){
        var w
        if(policy==='greedy') w = this.policyWhere(sim)
        else if(policy==='det') w = this.detWhere(sim)
        else if(policy==='crn') w = this.crnWhere(sim, rng)
        else { var pol=this._rolloutAI(); pol.gameData=sim; w=pol.where() }
        if (!w || w.x==null) break
        sim.putxy(w.x, w.y)
    }
}

// average rollout score-difference for a candidate under one policy
RolloutAI.prototype._evalCandidate = function(gd, c, me, R, policy){
    var sum = 0
    for (var r=0; r<R; r++){
        var sim = gd.fastClone()
        sim.putxy(c.x, c.y)            // EDGE_NOT: no score, turn flips
        // CRN: seed the local RNG from r only, so the SAME random sequence is
        // shared across all candidates for this rollout index.
        var rng = (policy==='crn') ? this._makeRng(r*2654435761 + 40503) : null
        this._rolloutToEnd(sim, policy, rng)
        sum += sim.player[me].score - sim.player[1-me].score
    }
    return sum / R
}

// choose the best safe edge by averaging rollout score-difference
RolloutAI.prototype.openingMove = function(gd){
    var me = gd.playerId
    var cands = this._openingCandidates(gd)
    var R = this.RO_ROLLOUTS
    var pol = this.RO_POLICY
    var best = cands[0], bestScore = -1e9
    for (var ci=0; ci<cands.length; ci++){
        var c = cands[ci]
        var score
        if(pol==='robust'){
            // worst-case across opponent models: be strong vs both OK and greedy
            score = Math.min(this._evalCandidate(gd,c,me,R,'ok'), this._evalCandidate(gd,c,me,R,'greedy'))
        } else {
            score = this._evalCandidate(gd,c,me,R,pol)
        }
        if (score > bestScore + 1e-9){ bestScore = score; best = c }
    }
    return best
}

RolloutAI.prototype.where = function(){
    var gd = this.gameData
    // pure opening: no immediate score available, safe moves remain
    if (gd.edgeCount[gd.EDGE_NOW]===0 && gd.edgeCount[gd.EDGE_NOT]>0){
        if (gd.edgeCount[gd.EDGE_NOT] <= this.RO_THRESH){
            return this.openingMove(gd)
        }
        // very early: cheap safe move (still no give-away)
        return this.getRandWhere(gd.EDGE_NOT)
    }
    // scoring / transition / sacrifice: OffensiveKeeperAI's control endgame
    return OffensiveKeeperAI.prototype.where.call(this)
}

