// candidate moves for the endgame (NOW>0 or forced sacrifice). Replaces OK's
// heuristic take/yield/sac with a rollout-evaluated choice, which avoids OK's
// known yield bugs (e.g. needlessly declining an R4 against a greedy taker).
RolloutAI.prototype._endgameCandidates = function(gd){
    var cands=[], seen={}
    var push=function(w){ if(w && w.x!=null){ var k=w.x+','+w.y; if(!seen[k]){seen[k]=1; cands.push(w)} } }
    if(gd.edgeCount[gd.EDGE_NOW]>0){
        // take options: one scoring edge per scoreable region
        for(var i=0;i<gd.scoreRegion.length;i++){
            push(gd.getOneEdgeFromRegionIndex(gd.scoreRegion[i]))
        }
        // a "yield" option: decline the free boxes and sacrifice into the
        // smallest non-scoreable region (only meaningful when control matters)
        var minr=null
        for(var idx in gd.connectedRegion){
            var r=gd.connectedRegion[idx]
            if(!r)continue
            if(gd.scoreRegion.indexOf(r.index)!==-1)continue
            if(minr==null || r.block.length<minr.block.length) minr=r
        }
        if(minr) push(gd.getOneEdgeFromRegion(minr))
        if(cands.length===0) push(gd.getAllEdges(gd.EDGE_NOW)[0])
        return cands
    }
    // forced sacrifice: one opening edge per region (consider all, not just smallest)
    var regs=[]
    for(var j in gd.connectedRegion){ var rr=gd.connectedRegion[j]; if(rr) regs.push(rr) }
    regs.sort(function(a,b){return a.block.length-b.block.length})
    for(var k=0;k<regs.length && cands.length<this.RO_MAX_CANDIDATES;k++){
        push(gd.getOneEdgeFromRegion(regs[k]))
    }
    if(cands.length===0) return [OffensiveKeeperAI.prototype.where.call(this)]
    return cands
}

