// Endgame move. Uses OffensiveKeeperAI's control logic, but surgically fixes
// its "yield" (decline free boxes to keep the offensive) decisions: when OK
// would yield while scoring edges exist, compare take-vs-yield by a quick
// deterministic OK rollout. This prevents the degenerate case where OK
// repeatedly yields R4s/L2s and a greedy opponent simply takes them all.
RolloutAI.prototype.endgameWhere = function(gd){
    var okMove = OffensiveKeeperAI.prototype.where.call(this)
    if(gd.edgeCount[gd.EDGE_NOW]>0 && gd.xy(okMove.x, okMove.y)===gd.EDGE_WILL){
        // OK chose to yield. Build take-vs-yield candidates and pick by rollout.
        var cands=[], seen={}
        var push=function(w){ if(w&&w.x!=null){var k=w.x+','+w.y; if(!seen[k]){seen[k]=1;cands.push(w)}} }
        for(var i=0;i<gd.scoreRegion.length;i++)
            push(gd.getOneEdgeFromRegionIndex(gd.scoreRegion[i]))
