// Chain-parity endgame formula. For a pure endgame (EDGE_NOT==0, EDGE_NOW==0,
// no cyclic regions) the optimal outcome is determined combinatorially:
//  - short chains (len<=2) are sacrificed first, alternating the sacrificer;
//    the first sacrificer S0 gets the even-indexed shorts, the opponent the odd.
//  - after `s` short chains, the long-chain sacrificer X is S0 iff s is even.
//  - in the long-chain phase the controller takes every long chain except the
//    last (double-crossing 2 back each); the sacrificer gets 2*(c-1).
// Returns {s0:finalScore, opp:finalScore} or null when not applicable (loops,
// or a free box present at the transition).
RolloutAI.prototype.evaluateEndgame = function(sim){
    if(sim.edgeCount[sim.EDGE_NOW]>0) return null
    var s0=sim.playerId
    var shorts=[], longs=[], hasLoop=false
    for(var idx in sim.connectedRegion){
        var r=sim.connectedRegion[idx]
        if(!r)continue
        if(r.isRing){hasLoop=true;break}
        var L=r.block.length
        if(L<=2)shorts.push(L); else longs.push(L)
    }
    if(hasLoop) return null
    shorts.sort(function(a,b){return a-b})
    var s=shorts.length, c=longs.length, Lsum=0
    for(var i=0;i<c;i++)Lsum+=longs[i]
    var s0short=0, oppshort=0
    for(var i=0;i<s;i++){ if(i%2===0)oppshort+=shorts[i]; else s0short+=shorts[i] }
    var longS0, longOpp
    if(c===0){longS0=0;longOpp=0}
    else if(s%2===0){longS0=2*(c-1);longOpp=Lsum-2*(c-1)}      // X = S0
    else {longOpp=2*(c-1);longS0=Lsum-2*(c-1)}                 // X = opp
    return {
        s0: sim.player[s0].score + s0short + longS0,
        opp: sim.player[1-s0].score + oppshort + longOpp
    }
}

