// play out `sim` to terminal using the rollout policy (mutates sim)
RolloutAI.prototype._rolloutToEnd = function(sim, policy, rng){
    policy = policy || 'ok'
    var guard=0
    while (sim.winnerId==null && guard++<400){
        // chain-parity fast-forward: once the pure endgame is reached, the
        // outcome is determined by the formula (deterministic, theory-based),
        // so skip simulating it — a low-variance, accurate leaf value.
        if(this.RO_USE_FORMULA && sim.edgeCount[sim.EDGE_NOT]===0){
            var fv=this.evaluateEndgame(sim)
            if(fv){
                var s0=sim.playerId
                sim.player[s0].score=fv.s0
                sim.player[1-s0].score=fv.opp
                sim.winnerId = fv.s0>=fv.opp ? s0 : (1-s0)
                break
            }
        }
        var w
        if(policy==='greedy') w = this.policyWhere(sim)
        else if(policy==='det') w = this.detWhere(sim)
        else if(policy==='crn') w = this.crnWhere(sim, rng)
        else { var pol=this._rolloutAI(); pol.gameData=sim; w=pol.where() }
        if (!w || w.x==null) break
        sim.putxy(w.x, w.y)
    }
}

