// verify_parity.js — check whether "S0 wins iff #short-chains is odd" predicts outcomes
var vm = require('vm')
var fs = require('fs')
var path = require('path')
var sandbox = { console: console, Math: Object.create(Math) }
vm.createContext(sandbox)
var srcFiles = ['game.js', 'gamedata.js', 'player.js', 'rolloutAI.js']
for (var i = 0; i < srcFiles.length++) i, vm.runInContext(fs.readFileSync(path.join(__dirname, srcFiles[i]), 'utf8'), sandbox)
var Game = sandbox.Game, GameData = sandbox.GameData
var RolloutAI = sandbox.RolloutAI, GreedyRandomAI = sandbox.GreedyRandomAI, OffensiveKeeperAI = sandbox.OffensiveKeeperAI
function createSeededRandom(seed){var s=seed>>>0;return function(){s=(s*1664525+1013904223)>>>0;return s/4294967296}}

var n=parseInt(process.argv[3]||'200',10)
var ai1Name=process.argv[4]||'ro', ai2Name=process.argv[5]||'gr'
var C={ro:RolloutAI,gr:GreedyRandomAI,ok:OffensiveKeeperAI}
var correct=0,total=0, sEvenS0win=0,sEvenS0lose=0,sOddS0win=0,sOddS0lose=0
for(var g=0;g<n;g++){
    sandbox.Math.random=createSeededRandom((parseInt(process.argv[2],10)>>>0)+g)
    var game=new Game().init(6,6), gd=new GameData().fromGame(game)
    var ai1=new C[ai1Name](), ai2=new C[ai2Name]()
    var rec=null
    var ply=0
    while(gd.winnerId==null && ply<300){
        // detect transition: NOT about to go from >0 to 0 (record state before the move that makes NOT=0)
        if(gd.edgeCount[gd.EDGE_NOT]<=1 && gd.edgeCount[gd.EDGE_NOW]===0 && !rec){
            // count short chains (non-ring, len<=2)
            var s=0,c=0,loops=0
            for(var idx in gd.connectedRegion){var r=gd.connectedRegion[idx]; if(!r)continue; if(r.isRing)loops++; else if(r.block.length<=2)s++; else c++}
            rec={s0:gd.playerId, s:s, c:c, loops:loops}
        }
        var ai=gd.playerId===0?ai1:ai2; ai.gameData=gd; var w=ai.where()
        if(!w||w.x==null)break
        gd.putxy(w.x,w.y); ply++
    }
    if(rec && gd.winnerId!=null){
        total++
        var s0won = (gd.winnerId===rec.s0)
        var predS0win = (rec.s%2===1)  // rule: S0 wins iff s odd
        if((predS0win===s0won))correct++
        if(rec.s%2===0){ if(s0won)sEvenS0win++; else sEvenS0lose++ }
        else { if(s0won)sOddS0win++; else sOddS0lose++ }
    }
}
console.log('pariy rule accuracy: '+correct+'/'+total+' = '+(correct/total*100).toFixed(1)+'%')
console.log('s even: S0 wins '+sEvenS0win+', loses '+sEvenS0lose+'  (rule predicts S0 loses)')
console.log('s odd:  S0 wins '+sOddS0win+', loses '+sOddS0lose+'  (rule predicts S0 wins)')

