// play out `sim` to terminal using the rollout policy (mutates sim)
RolloutAI.prototype._rolloutToEnd = function(sim, policy, rng, me){
    policy = policy || 'ok'
    var guard=0
    while (sim.winnerId==null && guard++<400){
        // chain-parity fast-forward: once the pure endgame is reached, the
        // outcome is determined by the formula (deterministic, theory-based),
        // so skip simulating it — a low-variance, accurate leaf value.
        if(this.RO_USE_FORMULA && sim.edgeCount[sim.EDGE_NOT]===0){
            var fv=this.evaluateEndgame(sim)
            if(fv){
                var s0=sim.playerId
                sim.player[s0].score=fv.s0
                sim.player[1-s0].score=fv.opp
                sim.winnerId = fv.s0>=fv.opp ? s0 : (1-s0)
                break
            }
        }
        var w
        if(policy==='greedy') w = this.policyWhere(sim)
        else if(policy==='det') w = this.detWhere(sim)
        else if(policy==='crn') w = this.crnWhere(sim, rng, me)
        else { var pol=this._rolloutAI(); pol.gameData=sim; w=pol.where() }
        if (!w || w.x==null) break
        sim.putxy(w.x, w.y)
    }
}

// average rollout score-difference for a candidate under one policy
RolloutAI.prototype._evalCandidate = function(gd, c, me, R, policy){
    var sum = 0
    for (var r=0; r<R; r++){
        var sim = gd.fastClone()
        sim.putxy(c.x, c.y)            // EDGE_NOT: no score, turn flips
        // CRN: seed the local RNG from r only, so the SAME random sequence is
        // shared across all candidates for this rollout index.
        var rng = (policy==='crn') ? this._makeRng(r*2654435761 + 40503) : null
        this._rolloutToEnd(sim, policy, rng, me)
        sum += sim.player[me].score - sim.player[1-me].score
    }
    return sum / R
}

