// average rollout score-difference for a candidate under one policy.
// asymMe: the root player index who keeps the strong OK endgame model; the
// opponent is modelled greedily. null => both sides use OK (symmetric).
RolloutAI.prototype._evalCandidate = function(gd, c, me, R, policy, asymMe){
    var sum = 0
    for (var r=0; r<R; r++){
        var sim = gd.fastClone()
        sim.putxy(c.x, c.y)            // EDGE_NOT: no score, turn flips
        // CRN: seed the local RNG from r only, so the SAME random sequence is
        // shared across all candidates for this rollout index.
        var rng = (policy==='crn') ? this._makeRng(r*2654435761 + 40503) : null
        this._rolloutToEnd(sim, policy, rng, asymMe)
        sum += sim.player[me].score - sim.player[1-me].score
    }
    return sum / R
}

// choose the best move among candidates by averaging rollout score-difference
RolloutAI.prototype._pickMove = function(gd, cands, R, policy){
    if(cands.length===1) return cands[0]
    var me = gd.playerId
    var asymMe = (policy==='crn') ? me : null
    var best = cands[0], bestScore = -1e9
    for (var ci=0; ci<cands.length; ci++){
        var c = cands[ci]
        var score
        if(policy==='robust'){
            // win under BOTH opponent models: greedy (asymmetric) and OK (symmetric)
            var g=this._evalCandidate(gd,c,me,R,'crn',me)
            var o=this._evalCandidate(gd,c,me,R,'crn',null)
