// endgame, "me" (asymMe) uses the strong OffensiveKeeperAI control play while the
// opponent uses the greedy model; asymMe==null => both use OffensiveKeeperAI.
RolloutAI.prototype.crnWhere = function(sim, rng, asymMe){
